import Foundation
import NIO
import NIOHTTP1
import NIOWebSocket

// Real-time chat server with cross-service JWT authentication
final class ChatServer {
    private let group: MultiThreadedEventLoopGroup
    private let authService: AuthenticationService
    private var connections: [ObjectIdentifier: WebSocketConnection] = [:]
    private let maxRecursionDepth = 256

    init(threads: Int = System.coreCount) {
        self.group = MultiThreadedEventLoopGroup(numberOfThreads: threads)
        self.authService = AuthenticationService()
    }

    func handleIncomingFrame(_ frame: WebSocketFrame, connection: WebSocketConnection) {
        guard let payload = frame.unmaskedData.getString(at: 0, length: frame.unmaskedData.readableBytes) else {
            return
        }
        processMessage(payload, connection: connection, depth: 0)
    }

    // Recursive message processor for nested protocol messages
    // Protocol supports embedded forwarding: {"forward": {"forward": {...}}}
    private func processMessage(_ raw: String, connection: WebSocketConnection, depth: Int) {
        guard depth < maxRecursionDepth else {
            connection.send(ErrorMessage.depthExceeded)
            return
        }

        guard let data = raw.data(using: .utf8),
              let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else {
            return
        }

        if let forwardPayload = json["forward"] as? [String: Any] {
            // Cross-service authentication check for forwarded messages
            if let serviceToken = json["service_token"] as? String {
                let authResult = authService.validateCrossServiceToken(
                    token: serviceToken,
                    claims: json,
                    stackBudget: getAvailableStackBudget()
                )
                if authResult.isValid {
                    if let nested = try? JSONSerialization.data(withJSONObject: forwardPayload),
                       let nestedStr = String(data: nested, encoding: .utf8) {
                        processMessage(nestedStr, connection: connection, depth: depth + 1)
                    }
                }
            }
        } else if let chatMessage = json["message"] as? String {
            broadcastMessage(chatMessage, from: connection)
        }
    }

    private func getAvailableStackBudget() -> Int {
        // Returns estimated remaining stack space in frames
        // On Linux/Swift, default thread stack is 8MB
        var stackSize: Int = 0
        withUnsafePointer(to: &stackSize) { ptr in
            stackSize = 8_388_608 - (Thread.callStackReturnAddresses.count * MemoryLayout<UnsafeRawPointer>.size)
        }
        return max(stackSize / 4096, 1)
    }

    private func broadcastMessage(_ message: String, from sender: WebSocketConnection) {
        for (_, conn) in connections where conn.id != sender.id {
            conn.send(ChatMessage(text: message, sender: sender.userId))
        }
    }
}

// Cross-service authentication with recursive claim validation
final class AuthenticationService {
    private let trustedServices: Set<String> = ["gateway", "relay", "federation"]

    struct AuthResult {
        let isValid: Bool
        let resolvedClaims: [String: Any]
    }

    func validateCrossServiceToken(token: String, claims: [String: Any], stackBudget: Int) -> AuthResult {
        // Validate the JWT structure (simplified)
        let parts = token.split(separator: ".")
        guard parts.count == 3 else {
            return AuthResult(isValid: false, resolvedClaims: [:])
        }

        // Decode claims from token payload
        guard let payloadData = Data(base64Encoded: String(parts[1]), options: .ignoreUnknownCharacters),
              let tokenClaims = try? JSONSerialization.jsonObject(with: payloadData) as? [String: Any] else {
            return AuthResult(isValid: false, resolvedClaims: [:])
        }

        guard let serviceName = tokenClaims["iss"] as? String,
              trustedServices.contains(serviceName) else {
            return AuthResult(isValid: false, resolvedClaims: [:])
        }

        // Resolve delegated claims recursively
        let resolved = resolveDelegatedClaims(tokenClaims, budget: stackBudget)
        return AuthResult(isValid: true, resolvedClaims: resolved)
    }

    // Resolves nested delegation chains in cross-service auth
    // Each delegation adds a stack frame with local claim buffers
    private func resolveDelegatedClaims(_ claims: [String: Any], budget: Int) -> [String: Any] {
        // Allocate local buffer for claim processing
        var localBuffer = [UInt8](repeating: 0, count: 2048)
        var resolved = claims

        if let delegatedTo = claims["delegate"] as? [String: Any] {
            // Budget check uses the CALLER's estimate, not actual remaining stack
            if budget > 0 {
                let innerResolved = resolveDelegatedClaims(delegatedTo, budget: budget - 1)
                resolved.merge(innerResolved) { current, _ in current }
            }
        }

        // Process claim transformations using local buffer
        if let rawClaim = claims["encoded_permissions"] as? String {
            let bytes = Array(rawClaim.utf8)
            let copyLen = min(bytes.count, localBuffer.count)
            localBuffer.replaceSubrange(0..<copyLen, with: bytes[0..<copyLen])
            resolved["permissions"] = String(bytes: localBuffer[0..<copyLen], encoding: .utf8)
        }

        return resolved
    }
}

struct WebSocketConnection {
    let id: UUID
    let userId: String
    func send(_ message: Any) { /* send to websocket */ }
}

enum ErrorMessage {
    case depthExceeded
}

struct ChatMessage {
    let text: String
    let sender: String
}
